/* ================= constants & helpers ================= */
const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const THRESHOLDS = [60, 65, 70, 75, 80, 85];
const pad = (n) => String(n).padStart(2, "0");
const ds = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const dayIdx = (d) => (d.getDay() + 6) % 7;
const fmt = (x) => `${+x.slice(0, 2) % 12 || 12}:${x.slice(3)}`;
const lsGet = (k, f) => { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : f; } catch (e) { return f; } };
const lsSet = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };

const SUBJECTS = [
  ["fsd", "Full Stack Development", "FSD", "#E5C07B"], ["asc", "AI & Soft Computing", "ASC", "#D9906A"],
  ["cp", "Competitive Programming", "CP", "#FBBF24"], ["lap", "Logical Aptitude", "LA", "#7FB5A6"],
  ["crt", "CRT Program", "CRT", "#E08A9A"], ["cs5", "Case Study V", "CS-V", "#6EC9A8"],
  ["se", "Software Engineering", "SE", "#B8A58A"], ["ads", "Adv. Data Structures & Algo", "ADSA", "#E8A06A"],
  ["nn", "Neural Networks", "NN", "#D4707F"],
].map(([id, name, short, color]) => ({ id, name, short, color, min: 60, base: { att: 0, miss: 0, off: 0 } }));

// [subject, start, end, type]; hours < 8 are PM
const T = (x) => { let [h, m] = x.split(":").map(Number); if (h < 8) h += 12; return `${pad(h)}:${pad(m)}`; };
const COMMON = {
  0: [["asc", "11:00", "12:30", "L"], ["fsd", "12:30", "1:30", "L"]],
  1: [["lap", "9:30", "11:00", ""]],
  2: [["fsd", "9:30", "10:30", "L"], ["se", "10:30", "12:00", "L"], ["cp", "12:00", "1:30", "L"]],
  3: [["cp", "12:00", "1:30", "L"], ["lap", "4:30", "5:30", ""]],
  4: [["crt", "9:30", "11:00", ""], ["se", "11:30", "1:00", "L"], ["asc", "2:30", "4:00", "L"], ["cs5", "4:00", "5:00", ""]],
};
const SEC = {
  A: {
    0: [["ads", "9:30", "11:00", "L"], ["cp", "2:30", "5:30", "P"]],
    1: [["fsd", "11:00", "1:30", "P"], ["ads", "2:30", "3:30", "L"], ["se", "3:30", "5:00", "T"]],
    2: [["asc", "2:30", "5:00", "P"]], 3: [["nn", "2:30", "4:30", "P"]],
  },
  B: {
    0: [["nn", "9:30", "11:00", "L"], ["asc", "2:30", "5:00", "P"]],
    1: [["cp", "11:00", "1:30", "P"], ["nn", "2:30", "3:30", "L"]],
    2: [["fsd", "2:30", "5:00", "P"]], 3: [["ads", "2:30", "4:30", "P"]],
  },
};
function buildTT(sec) {
  const tt = {};
  for (let d = 0; d < 7; d++)
    tt[d] = [...(COMMON[d] || []), ...(SEC[sec][d] || [])]
      .map(([sid, s, e, t]) => ({ sid, s: T(s), e: T(e), t }))
      .sort((a, b) => a.s.localeCompare(b.s));
  return tt;
}
const rkey = (en) => `${en.sid}@${en.s}`;

function makeData(history) {
  const timetable = buildTT("A");
  const records = {};
  if (history) {
    const today = new Date(); today.setHours(0, 0, 0, 0);
    for (let i = 40; i >= 1; i--) {
      const d = new Date(today); d.setDate(d.getDate() - i);
      timetable[dayIdx(d)].forEach((en, j) => {
        const h = (i * 31 + j * 17 + en.sid.length * 7) % 100;
        const st = h < 72 ? "att" : h < 90 ? "miss" : h < 95 ? "off" : null;
        if (st) (records[ds(d)] ||= {})[rkey(en)] = st;
      });
    }
  }
  return { section: "A", subjects: SUBJECTS, timetable, records, defaultMin: 60 };
}

function statsFor(sub, records) {
  let { att, miss, off } = sub.base;
  Object.values(records).forEach((day) => Object.entries(day).forEach(([k, v]) => {
    if (k.split("@")[0] !== sub.id) return;
    if (v === "att") att++; else if (v === "miss") miss++; else if (v === "off") off++;
  }));
  const cond = att + miss, pct = cond ? (att / cond) * 100 : 100, m = sub.min / 100, safe = pct >= sub.min;
  let text;
  if (safe) { const x = Math.floor(att / m - cond + 1e-9); text = x > 0 ? `can miss ${x} lecture${x > 1 ? "s" : ""}` : "can't miss the next lecture"; }
  else { const n = Math.ceil((m * cond - att) / (1 - m) - 1e-9); text = `need to attend ${n} lecture${n > 1 ? "s" : ""}`; }
  return { att, miss, off, cond, tot: cond + off, pct, safe, text };
}


