function Ring({ pct, safe, size = 58 }) {
  const r = (size - 8) / 2, c = 2 * Math.PI * r;
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg width={size} height={size} className="-rotate-90">
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#26262C" strokeWidth="6" />
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="6" strokeLinecap="round"
          stroke={safe ? "#34D399" : "#FB7185"} strokeDasharray={c} strokeDashoffset={c * (1 - Math.min(100, pct) / 100)}
          style={{ transition: "stroke-dashoffset .5s" }} />
      </svg>
      <span className={`absolute inset-0 flex items-center justify-center text-[13px] font-extrabold tabular-nums ${safe ? "text-[#6EE7B7]" : "text-[#FDA4AF]"}`}>
        {Math.round(pct)}%
      </span>
    </div>
  );
}

